<?php require_once __DIR__.'/auth.php';$user=require_role('supervisor');require_once __DIR__.'/partials/layout.php';layout_start('Escanear QR',$user,'escaner');?><a class="module-back" href="panel.php">← Volver al escritorio</a><section class="module-card"><h1>Escanear código QR</h1><p>Apunta la cámara al código QR pegado en el carro.</p><?php if(empty($_SERVER['HTTPS'])||$_SERVER['HTTPS']==='off'): ?><div class="module-alert warn">La cámara puede ser bloqueada. Usa HTTPS en el dominio del hosting.</div><?php endif;?><div id="reader"></div><p id="status" role="status"></p></section><script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>const status=document.getElementById('status');function onScan(decoded){try{const u=new URL(decoded,location.origin),c=u.searchParams.get('carro');if(c){status.textContent='Código detectado. Abriendo historial…';location.href='ver.php?carro='+encodeURIComponent(c);return;}}catch(e){}const c=decoded.trim();if(/^[A-Za-z0-9_-]{1,80}$/.test(c)){location.href='ver.php?carro='+encodeURIComponent(c);return;}status.textContent='El QR no contiene un código de carro válido.'}new Html5QrcodeScanner('reader',{fps:10,qrbox:{width:250,height:250}},false).render(onScan,()=>{});</script><?php layout_end();
